const t = $input.first().json.body || $input.first().json;
const dir = t.direction || '?';
const asset = t.asset || '?';
const fill = t.fill_price ? Number(t.fill_price).toFixed(2) : '?';
const size = t.size_pct ? (t.size_pct * 100).toFixed(2) + '%' : '?';
const sl = t.stop_loss ? Number(t.stop_loss).toFixed(2) : '?';
const tp = t.take_profit ? Number(t.take_profit).toFixed(2) : '?';
const slip = t.slippage_pct ? (t.slippage_pct * 100).toFixed(4) + '%' : '?';
const regime = t.regime || '?';
const session = t.session || '?';
const conf = t.confidence ? (t.confidence * 100).toFixed(1) + '%' : '?';
const broker = t.broker || 'unknown';
const expiry = t.expiry_at ? new Date(t.expiry_at).toISOString().slice(11,16) + ' UTC' : '?';
const isXau = asset === 'XAU/USD';
const isInverse = asset === 'DUST';
const emoji = dir === 'BUY' && !isInverse ? '🟢' : isInverse ? '🔻' : '🔴';
const label = isXau ? 'SIMULATED' : isInverse ? 'SELL→DUST' : 'PAPER';
const msg = [
  emoji + ' **' + dir + ' ' + asset + '** [' + label + ']',
  'Fill: $' + fill + ' | Size: ' + size + ' of NAV',
  'Stop: $' + sl + ' | Target: $' + tp,
  'Expires: ' + expiry + ' | Confidence: ' + conf,
  'Slippage: ' + slip + ' | Regime: ' + regime + ' | Session: ' + session,
].join('\n');
return [{ json: { message: msg, dir, asset } }];
